-- Table structure for table `tbl_marcas_solicitudes`
--

DROP TABLE IF EXISTS `tbl_marcas_solicitudes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_marcas_solicitudes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cod_contador` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `tipo_registro_id` int(11) NOT NULL,
  `client_id` int(11) DEFAULT NULL COMMENT 'FK con la tabla tblclients',
  `oficina_id` int(11) NOT NULL,
  `staff_id` int(11) DEFAULT NULL COMMENT 'FK con la tabla staff',
  `signo_archivo` varchar(255) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `signonom` varchar(255) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `tipo_signo_id` int(11) DEFAULT NULL,
  `tipo_solicitud_id` int(11) DEFAULT NULL,
  `ref_interna` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `primer_uso` date DEFAULT NULL,
  `ref_cliente` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `prueba_uso` date DEFAULT NULL,
  `carpeta` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `libro` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `folio` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `tomo` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `comentarios` text COLLATE utf8mb4_spanish_ci,
  `estado_id` int(11) DEFAULT NULL,
  `solicitud` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `fecha_solicitud` date DEFAULT NULL,
  `registro` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `fecha_registro` date DEFAULT NULL,
  `certificado` varchar(20) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `fecha_certificado` date DEFAULT NULL,
  `fecha_vencimiento` date DEFAULT NULL,
  `signo_archivo_desc` varchar(100) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tbl_estados_tbl_marcas_solicitudes_fk` (`estado_id`),
  KEY `tbl_tipo_sol_mar_sol_fk` (`tipo_solicitud_id`),
  KEY `tbl_tipo_signo_mar_sol_fk` (`tipo_signo_id`),
  KEY `tbl_mar_tipo_reg_mar_sol_fk` (`tipo_registro_id`),
  KEY `tbl_oficina_tbl_marcas_solicitudes_fk` (`oficina_id`),
  CONSTRAINT `estado_marcas_fk` FOREIGN KEY (`estado_id`) REFERENCES `tbl_estado_expediente` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `oficina_marcas_fk` FOREIGN KEY (`oficina_id`) REFERENCES `tbl_oficina` (`oficina_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tbl_estados_tbl_marcas_solicitudes_fk` FOREIGN KEY (`estado_id`) REFERENCES `tbl_estado_expediente` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tbl_mar_tipo_reg_mar_sol_fk` FOREIGN KEY (`tipo_registro_id`) REFERENCES `tbl_marcas_tipo_registro` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tbl_oficina_tbl_marcas_solicitudes_fk` FOREIGN KEY (`oficina_id`) REFERENCES `tbl_oficina` (`oficina_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tbl_tipo_signo_mar_sol_fk` FOREIGN KEY (`tipo_signo_id`) REFERENCES `tbl_tipo_signo` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tbl_tipo_sol_mar_sol_fk` FOREIGN KEY (`tipo_solicitud_id`) REFERENCES `tbl_tipo_solicitud` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tipo_registro_marcas_fk` FOREIGN KEY (`tipo_registro_id`) REFERENCES `tbl_marcas_tipo_registro` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tipo_signo_marcas_fk` FOREIGN KEY (`tipo_signo_id`) REFERENCES `tbl_tipo_signo` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `tipo_solicitud_fk` FOREIGN KEY (`tipo_solicitud_id`) REFERENCES `tbl_tipo_solicitud` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30328 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci COMMENT='Tabla maestra donde estan las solicitudes de marcas';
/*!40101 SET character_set_client = @saved_cs_client */;

