,NULL,NULL,NULL,NULL,NULL),(2300,3,NULL,1,1,'11','UNA COMPOSICIÓN FARMACÉUTICA DE LIPOSOMAS DE TAMAÑO PEQUEÑO Y MÉTODO DE PREPARACIÓN','Una composición farmacéutica de liposomas de tamaño pequeño, unilamelares para el suministro de compuestos activos, por vía inyectable, con mejorada permanencia en el torrente sanguíneo, donde la membrana unilameral contiene una mezcla de lípidos saturados que comprende al menos un lisofosfolípido en una cantidad comprendida entre aproximadamente 0,5 moles % y aproximadamente 6,0 moles% respecto de los lípidos totales y método de preparación. Adicionalmente se preparan liposomas con mayor eficiencia de encapsulamiento de un principio activo tal como doxorubicina mediante el agregado de una solución de iones calcio.','P=A61K 9/00','P000148',NULL,NULL,NULL,NULL,NULL,61,'2003-001456','2003-08-26',NULL,NULL,NULL,NULL,'2003-001456','2003-08-26',NULL,NULL,NULL,NULL,NULL,NULL),(2301,3,NULL,1,1,'11','UN PROCEDIMIENTO DE OBTENCIÓN DE BENCENSULFONATO DE 4(2-CLOROFENIL)-2-[(2 AMINOETOXI) METILEN]-3-ETOXICARBONIL-5-METOXICARBONIL-6-METIL-1,4-DIHIDROPIRINA','UN PROCEDIMIENTO PARA LA OBTENCION DIRECTA DE BESIATO DE AMLODIPINA A PARTIR DEL FTALOIL DERIVADO CONVENIENTE, SIN AISLACION DE LA BASE AMLODIPINA, DE LA FORMULA I.','P=C07D 211/90','P000149',NULL,NULL,NULL,NULL,NULL,173,'1995-002203','1995-12-19',NULL,NULL,NULL,NULL,'1995-002203','1995-12-19','A057346','1995-12-19',NULL,NULL,NULL,NULL),(2302,3,NULL,1,1,'11','UNIÓN SOLDADA PROTEGIDA PARA TUBERÍAS DE TRANSPORTE DE FLUIDOS Y PROCEDIMIENTO PARA SU OBTENCIÓN',NULL,'P=F16B 1/00','P000150',NULL,NULL,NULL,NULL,NULL,88,'2001-001873','2001-08-30',NULL,NULL,NULL,NULL,'2001-001873','2001-08-30',NULL,NULL,NULL,NULL,NULL,NULL),(2303,3,NULL,1,1,'11','ACERO CARBONO DE BAJA ALEACION PARA LA FABRICACION DE TUBERIAS PARA EXPLORACION Y PRODUCCION DE PETROLEO Y/O GAS NATURAL, CON MEJORADA RESISTENCIA A LA CORROSION, PROCEDIMIENTO PARA FABRICAR TUBOS SIN COSTURA Y TUBOS SIN COSTURA OBTENIDOS',NULL,'P=C22C 38/18 